#define MULIB_IMPL_ENDIAN
#define MULIB_IMPL_COFF
#define MULIB_IMPL_PE
#define MULIB_IMPL_STRBUF
#define MULIB_IMPL_SHIRAZ
#define MULIB_IMPL_PEBUILDER
#define MULIB_IMPL_OBJFILEBUILDER
#define MULIB_IMPL_OBJFILEWRITER
#define MULIB_IMPL_BINFILEWRITER
#define MULIB_IMPL_BYCUTILS
#define MULIB_IMPL_BUFFER
#include "mulib-shiraz.h"
#include "mulib-pebuilder.h"
#include <assert.h>

int main(void) {
    /* mov eax,42; ret -- a real Windows PE32+ executable generated by MuLIB. */
    const unsigned char code[]={0xb8,42,0,0,0,0xc3};
    mulib_buffer_t pe={0}; mulib_shiraz_t *vm=NULL; mulib_strbuf_t aot={0};
    assert(mulib_pebuilder_text(&pe,code,sizeof(code),0));
    assert(!mulib_shiraz_load(&vm,pe.data,pe.length,NULL,NULL));
    assert(!mulib_shiraz_emit_c(vm,0,&aot));
    assert(strstr(aot.data,"mulib_shiraz_execute"));
    assert(mulib_shiraz_run(vm,100)==MULIB_SHIRAZ_DONE);
    assert(mulib_shiraz_cpu(vm)->exit_code==42);
    puts("Shiraz: interpreted PE exit=42; generated C AOT source.");
    mulib_strbuf_free(&aot); mulib_shiraz_destroy(vm); mulib_buffer_free(&pe);
    return 0;
}
